146	    /** The sheet's claims, newest first by their place in the list. */
147	    @Transactional(readOnly = true)
148	    public List<Claim> list(String sheetId) {
149	        return claims.findBySheetIdOrderByListedDesc(sheetId);
150	    }
151	
152	    /** Add a claim to a person; a claim with no date is dated the sheet's today. */
153	    @Transactional
154	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
155	            String corrects) {
156	        Person person = person(sheetId, personId);
157	        LocalDate dated = dateOr(sheetId, date);
158	        refuseIfClosed(sheetId, dated);
159	        refuseIfRetired(person, dated);
160	        refuseIfNotCorrecting(sheetId, personId, amount, corrects);
161	        Rollup.Snapshot before = rollup.snapshot(sheetId);
162	        // The due-by is fixed now, from the terms of the person's grade in force on the claim's date.
163	        Claim claim = new Claim(sheetId, personId, amount, dated, noteOf(note), corrects,
164	                settings.terms(sheetId, person.gradeOn(dated), dated));
165	        // The sheet is locked (refuseIfClosed), so no other claim takes the same place.
166	        claim.setListed(claims.lastListed(sheetId) + 1);
167	        claim = claims.saveAndFlush(claim);
168	        logStatus(sheetId, user, person, claim);
169	        recordChange("CLAIM_ADDED", user, person, claim);
170	        rollup.recordChanges(user, before);
171	        return claim;
172	    }
173	
174	    /** Change a draft claim's amount, date and note; a blank date takes the sheet's today. A claim that
175	     *  is no longer a draft is refused: to change an open claim, void it and add a new one. */
176	    @Transactional
177	    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note,
178	            String corrects) {
179	        Claim claim = claims.findForUpdate(id, sheetId)
180	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
181	        LocalDate dated = dateOr(sheetId, date);
182	        refuseIfClosed(sheetId, claim.getDate());
183	        refuseIfClosed(sheetId, dated);
184	        if (claim.getStatus() != ClaimStatus.DRAFT) {
185	            throw new ResponseStatusException(HttpStatus.CONFLICT,
186	                    "A " + claim.getStatus() + " claim cannot be edited; only a DRAFT can.");
187	        }
188	        refuseIfRetired(person(sheetId, claim.getPersonId()), dated);
189	        refuseIfNotCorrecting(sheetId, claim.getPersonId(), amount, corrects);
190	        Rollup.Snapshot before = rollup.snapshot(sheetId);
191	        claim.set(amount, dated, noteOf(note), corrects);
192	        Claim saved = claims.saveAndFlush(claim);
193	        recordChange("CLAIM_EDITED", user, person(sheetId, saved.getPersonId()), saved);
194	        rollup.recordChanges(user, before);
195	        return saved;
196	    }
197	
198	    /** Move a claim to a new status; a change its status does not allow is refused, as is settling
199	     *  by the user who opened the claim. A clerk's settling of a claim whose due is above the sheet's
200	     *  clerk limit leaves it PENDING for a steward to approve (a due of n/a is within any limit; a
201	     *  steward settles anything). */
202	    @Transactional
203	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus next) {
204	        Claim claim = claims.findForUpdate(id, sheetId)
205	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
206	        refuseIfClosed(sheetId, claim.getDate());
207	        if (!claim.getStatus().canBecome(next)) {
208	            throw new ResponseStatusException(HttpStatus.CONFLICT,
209	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
210	        }
211	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
212	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
213	                    "The user who opened a claim cannot settle it.");
214	        }
215	        Person person = person(sheetId, claim.getPersonId());
216	        // Worked out while the claim is still open: settling freezes the due, its late charge included.
217	        BigDecimal dueNow = next == ClaimStatus.SETTLED ? due(sheetId, person, claim) : null;
218	        if (next == ClaimStatus.SETTLED && isAboveClerkLimit(sheetId, user, dueNow)) next = ClaimStatus.PENDING;
219	        Rollup.Snapshot before = rollup.snapshot(sheetId);
220	        String number = next == ClaimStatus.OPEN ? nextNumber(sheetId, claim) : claim.getNumber();
221	        claim.setStatus(next);
222	        if (next == ClaimStatus.OPEN) claim.setOpenedBy(user);
223	        // A voided claim keeps its number, which is never given to another claim.
224	        claim.setNumber(number);
225	        if (next == ClaimStatus.SETTLED) claim.setSettledDue(dueNow);
226	        logStatus(sheetId, user, person, claim);
227	        Claim saved = claims.saveAndFlush(claim);
228	        String event = EVENTS.get(next);
229	        if (next == ClaimStatus.SETTLED) {
230	            recordChange(event, user, person, saved, number, " due=" + text(saved.getSettledDue()));
231	        } else {
232	            recordChange(event, user, person, saved, number, "");
233	        }
234	        rollup.recordChanges(user, before);
235	        return saved;
236	    }
237	
238	    /** Move a DRAFT, OPEN or PENDING claim to another person on the sheet, as their newest claim. It
239	     *  keeps its number and date and loses any figure a statement bound it to (it is live again until
240	     *  its new person's next statement). Refused unless the user is a steward of the sheet, and for a
241	     *  settled or voided claim, a claim dated inside a closed period, a move to the claim's own person,
242	     *  or to a person retired by the claim's date. */
243	    @Transactional
244	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
245	        Claim claim = claims.findForUpdate(id, sheetId)
246	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
247	        refuseIfClosed(sheetId, claim.getDate());
248	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
249	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward moves a claim to another person.");
250	        }
251	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
252	            throw new ResponseStatusException(HttpStatus.CONFLICT,
253	                    "A " + claim.getStatus() + " claim cannot be moved to another person.");
254	        }
255	        Person from = person(sheetId, claim.getPersonId());
256	        Person to = person(sheetId, toPersonId);
257	        if (from.getId().equals(to.getId())) {
258	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already " + to.getName() + "'s.");
259	        }
260	        refuseIfRetired(to, claim.getDate());
261	        Rollup.Snapshot before = rollup.snapshot(sheetId);
262	        claim.moveTo(to.getId(), claims.lastListed(sheetId) + 1);
263	        Claim saved = claims.saveAndFlush(claim);
264	        recordChange("CLAIM_REASSIGNED", user, to, saved, saved.getNumber(),
265	                " from=" + from.getName() + " to=" + to.getName());
266	        rollup.recordChanges(user, before);
267	        return saved;
268	    }
269	
270	    /** Approve a PENDING claim: it is SETTLED, its due (its live figure and any late charge) frozen
271	     *  now. Refused unless the user is a steward of the sheet other than the one who opened it. */
272	    @Transactional
273	    public Claim approve(String sheetId, String user, long id) {
274	        Claim claim = pending(sheetId, user, id);
275	        if (user.equals(claim.getOpenedBy())) {
276	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
277	                    "The user who opened a claim cannot approve it.");
278	        }
279	        Person person = person(sheetId, claim.getPersonId());
280	        BigDecimal dueNow = due(sheetId, person, claim);
281	        Rollup.Snapshot before = rollup.snapshot(sheetId);
282	        claim.setStatus(ClaimStatus.SETTLED);
283	        claim.setSettledDue(dueNow);
284	        logStatus(sheetId, user, person, claim);
285	        Claim saved = claims.saveAndFlush(claim);
286	        recordChange("CLAIM_APPROVED", user, person, saved, saved.getNumber(), " due=" + text(saved.getSettledDue()));
287	        rollup.recordChanges(user, before);
288	        return saved;
289	    }
290	
291	    /** Re-settle a SETTLED claim: its due is frozen again at what it would be today as an open claim
292	     *  bound by no statement (today's rates, grades, floor and late charge). Refused unless the user is
293	     *  a steward of the sheet, and for a claim that is not SETTLED or is dated inside a closed period. */
294	    @Transactional
295	    public Claim resettle(String sheetId, String user, long id) {
296	        Claim claim = claims.findForUpdate(id, sheetId)
297	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
298	        refuseIfClosed(sheetId, claim.getDate());
299	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
300	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim.");
301	        }
302	        if (claim.getStatus() != ClaimStatus.SETTLED) {
303	            throw new ResponseStatusException(HttpStatus.CONFLICT,
304	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can.");
305	        }
306	        Person person = person(sheetId, claim.getPersonId());
307	        BigDecimal old = claim.getSettledDue();
308	        BigDecimal dueNow = LateCharge.dueAsOpen(claim, dueNow(sheetId, person, claim), sheets.today(sheetId),
309	                settings.latePct(sheetId, claim.getDate()), rounding(sheetId, claim));
310	        Rollup.Snapshot before = rollup.snapshot(sheetId);
311	        claim.setSettledDue(dueNow);
312	        logStatus(sheetId, user, person, claim);
313	        Claim saved = claims.saveAndFlush(claim);
314	        recordChange("CLAIM_RESETTLED", user, person, saved, saved.getNumber(),
315	                " old=" + text(old) + " new=" + text(saved.getSettledDue()));
316	        rollup.recordChanges(user, before);
317	        return saved;
318	    }
319	
320	    /** Reject a PENDING claim for a reason: it is OPEN again, bound again by its person's last
321	     *  statement if that statement bound it. Refused unless the user is a steward of the sheet. */
322	    @Transactional
323	    public Claim reject(String sheetId, String user, long id, String reason) {
324	        Claim claim = pending(sheetId, user, id);
325	        Person person = person(sheetId, claim.getPersonId());
326	        Rollup.Snapshot before = rollup.snapshot(sheetId);
327	        claim.setStatus(ClaimStatus.OPEN);
328	        logStatus(sheetId, user, person, claim);
329	        Claim saved = claims.saveAndFlush(claim);
330	        recordChange("CLAIM_REJECTED", user, person, saved, saved.getNumber(), " reason=" + reason);
331	        rollup.recordChanges(user, before);
332	        return saved;
333	    }
334	
335	    /** The PENDING claim a steward approves or rejects, locked; refused when it is not PENDING, is
336	     *  dated inside a closed period, or the user is not a steward of the sheet. */
337	    private Claim pending(String sheetId, String user, long id) {
338	        Claim claim = claims.findForUpdate(id, sheetId)
339	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
340	        refuseIfClosed(sheetId, claim.getDate());
341	        if (claim.getStatus() != ClaimStatus.PENDING) {
342	            throw new ResponseStatusException(HttpStatus.CONFLICT,
343	                    "A " + claim.getStatus() + " claim is not waiting for approval.");
344	        }
345	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
346	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward approves or rejects a claim.");
347	        }
348	        return claim;
349	    }
350	
351	    private static final Map<ClaimStatus, String> EVENTS = Map.of(
352	            ClaimStatus.OPEN, "CLAIM_OPENED", ClaimStatus.PENDING, "CLAIM_PENDING",
353	            ClaimStatus.SETTLED, "CLAIM_SETTLED", ClaimStatus.VOID, "CLAIM_VOIDED");
354	
355	    private static String text(BigDecimal due) {
356	        return due == null ? "n/a" : due.toPlainString();
357	    }
358	
359	    /** The number a claim takes as it is opened: while the sheet's period numbering is in force (its
360	     *  today on or after the setting's date), the next of the claim's period, <period name>-<n>, or of
361	     *  claims in no period, X-<n>; otherwise the sheet's next sheet-wide number. */
362	    private String nextNumber(String sheetId, Claim claim) {
363	        LocalDate from = settings.periodNumberingFrom(sheetId);
364	        if (from == null || sheets.today(sheetId).isBefore(from)) {
365	            return Integer.toString(sheets.nextClaimNumber(sheetId));
366	        }
367	        Period period = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
368	                .filter((p) -> p.contains(claim.getDate())).findFirst().orElse(null);
369	        if (period == null) return "X-" + sheets.nextSequenceNumber(sheetId, "none");
370	        return period.getName() + "-" + sheets.nextSequenceNumber(sheetId, "period:" + period.getId());
371	    }
372	
373	    /** Whether the user is a clerk settling a claim whose due is above the sheet's clerk limit. */
374	    private boolean isAboveClerkLimit(String sheetId, String user, BigDecimal due) {
375	        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return false;
376	        BigDecimal limit = settings.clerkLimit(sheetId);
377	        return limit != null && due.compareTo(limit) > 0;
378	    }
379	
380	    /** Refuse a change to a claim dated inside a closed period. The sheet is locked first, as closing
381	     *  a period locks it, so a claim cannot change in a period while it is being closed. */
382	    private void refuseIfClosed(String sheetId, LocalDate date) {
383	        sheetRows.findForUpdate(sheetId);
384	        if (periods.isClosedOn(sheetId, date)) {
385	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is dated inside a closed period.");
386	        }
387	    }
388	
389	    /** Refuse a correction (a negative amount) unless it names, by number, a settled claim of the same person. */
390	    private void refuseIfNotCorrecting(String sheetId, long personId, BigDecimal amount, String corrects) {
391	        if (amount.signum() >= 0) return;
392	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
393	                .filter(c -> c.getStatus() == ClaimStatus.SETTLED).isPresent();
394	        if (!settled) {
395	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
396	                    "A negative amount must name, by number, a settled claim of the same person that it corrects.");
397	        }
398	    }
399	
400	    /** Refuse a claim dated after its person's retirement date. */
401	    private static void refuseIfRetired(Person person, LocalDate date) {
402	        if (person.isRetiredOn(date)) {
403	            throw new ResponseStatusException(HttpStatus.CONFLICT,
404	                    "The claim is dated after " + person.getName() + " retired.");
405	        }
406	    }
407	
408	    private Person person(String sheetId, long personId) {
409	        return people.findByIdAndSheetId(personId, sheetId)
410	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
411	    }
412	
413	    /** What is due on the claim now: its figure with the late charge on top while it is open and
414	     *  overdue (the charge is never bound by a statement); null when the figure is n/a. */
415	    public BigDecimal due(String sheetId, Person person, Claim claim) {
416	        return LateCharge.dueOf(claim, figure(sheetId, person, claim), sheets.today(sheetId),
417	                settings.latePct(sheetId, claim.getDate()), rounding(sheetId, claim));
418	    }
419	
420	    /** The figure under the claim's due, before any late charge: the due fixed when it was settled, else the figure
421	     *  its person's last statement bound it to (unless it is PENDING, which no statement binds), else its live due;
422	     *  null when that is n/a. */
423	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
424	        if (claim.getSettledDue() != null) return claim.getSettledDue();
425	        if (claim.isBound()) return claim.getStatedDue();
426	        return dueNow(sheetId, person, claim);
427	    }
428	
429	    /** What is due on the claim now at the rate in force on the claim's date of its person's grade in
430	     *  force on that date, rounded
431	     *  as the claim's {@link Rounding} decides and at least the sheet's floor (a correction has no floor); null when no rate of the
432	     *  grade applies by then. */
433	    private BigDecimal dueNow(String sheetId, Person person, Claim claim) {
434	        Rate rate = rates.inForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
435	        if (rate == null) return null;
436	        BigDecimal due = claim.getAmount().multiply(rate.getPct()).divide(BigDecimal.valueOf(100), 2,
437	                rounding(sheetId, claim));
438	        return claim.isCorrection() ? due : due.max(settings.floor(sheetId, claim.getDate()));
439	    }
440	
441	    /** How the claim's live figures round under the sheet's policy date: by the date of the claim a
442	     *  correction corrects, else by its own. */
443	    private RoundingMode rounding(String sheetId, Claim claim) {
444	        Claim corrected = claim.isCorrection() && claim.getCorrects() != null
445	                ? claims.findBySheetIdAndPersonIdAndNumber(sheetId, claim.getPersonId(), claim.getCorrects()).orElse(null)
446	                : null;
447	        return Rounding.of(Rounding.dateOf(claim, corrected),
448	                Rounding.policyDate(settings.policyDate(sheetId), sheets.today(sheetId)));
449	    }
450	
451	    /** Log the status the claim has just taken, with its due as worked out now. */
452	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
453	        claim.logStatus(user, sheets.today(sheetId), due(sheetId, person, claim));
454	    }
455	
456	    private void recordChange(String event, String user, Person person, Claim claim) {
457	        recordChange(event, user, person, claim, claim.getNumber(), "");
458	    }
459	
460	    /** The claim's audit line; a claim with a number carries it, then any extra fields. */
461	    private void recordChange(String event, String user, Person person, Claim claim, String number, String extra) {
462	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
463	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
464	                + (number == null ? "" : " number=" + number) + extra);
465	    }
466	
467	    private LocalDate dateOr(String sheetId, LocalDate date) {
468	        return date != null ? date : sheets.today(sheetId);
469	    }
470	
471	    private static String noteOf(String note) {
472	        return note == null ? "" : note.trim();
473	    }
474	}
